args.query:
WITH v AS (
  SELECT c.customer_unique_id, o.order_purchase_timestamp
  FROM orders o JOIN customers c ON o.customer_id = c.customer_id
  WHERE o.order_status NOT IN ('canceled','unavailable')
),
f AS (
  SELECT customer_unique_id, MIN(order_purchase_timestamp) AS first_order FROM v GROUP BY 1
)
SELECT COUNT(*) AS new_customers_2018 FROM f WHERE first_order >= '2018-01-01' AND first_order < '2019-01-01';
